pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 amount) public {
        // Ensure user is non-zero for call power
        vm.assume(user != address(0));
        // Bound amount to prevent overflow but allow zero
        amount = bound(amount, 0, 1e30);

        // Give user ether if needed
        vm.deal(user, amount);

        // Record balance before
        uint256 balanceBefore = c.getBalance(user);

        // Prank as user and call addToBalance with value = 0
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("addToBalance()"));

        // General rule: adding zero value should not revert and should not change balance
        assertTrue(success && c.getBalance(user) == balanceBefore);
    }
}

