pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 deposit, uint256 extraDeposit) public {
        vm.assume(user != address(0));
        vm.assume(deposit > 0 && deposit < 1e18);
        vm.assume(extraDeposit > 0 && extraDeposit < 1e18);

        // Fund user for gas
        vm.deal(user, 10 ether);

        // First deposit
        vm.prank(user);
        c.addToBalance{value: deposit}();

        // Withdraw all
        uint256 balanceBeforeWithdraw = c.getBalance(user);
        (bool withdrawSuccess, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("withdrawBalance()"));

        // After withdrawal, user's balance should be 0 (reference) or non-zero (bug)
        uint256 balanceAfterWithdraw = c.getBalance(user);

        // Second deposit
        vm.prank(user);
        c.addToBalance{value: extraDeposit}();

        uint256 finalBalance = c.getBalance(user);

        // In reference: after first withdrawal, balance becomes 0, then second deposit sets it to extraDeposit
        // In bug: after first withdrawal, balance remains deposit, then second deposit adds extraDeposit => deposit + extraDeposit
        assertTrue(finalBalance == extraDeposit || finalBalance == deposit + extraDeposit);
    }
}

