// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address user, uint256 deposit, uint256 withdrawAmount) public {
        // Bound inputs to avoid overflow/underflow in direct calls
        vm.assume(withdrawAmount <= deposit); // we will deposit first then withdraw a smaller amount
        vm.assume(user != address(0));

        // Prepare user balance
        vm.deal(user, deposit);
        vm.prank(user);
        c.addToBalance{value: deposit}();

        // Now withdraw (but amount may be less than deposit to avoid revert in reference)
        // We use the actual balance after deposit
        uint256 balanceBeforeWithdraw = c.getBalance(user);
        vm.assume(withdrawAmount <= balanceBeforeWithdraw);

        // Perform the withdrawal (this is the buggy line in M: no balance reset)
        // We'll call withdrawBalance directly, which in P would reset the balance
        vm.prank(user);
        c.withdrawBalance();

        // Now add some more value
        vm.deal(user, 1 ether);
        vm.prank(user);
        c.addToBalance{value: 1 ether}();

        // The invariant: the balance after the second addToBalance is at least 1 ether
        // In the reference P, the balance was reset to 0 after withdraw, then +1 ether gives exactly 1 ether.
        // In M, the balance was NOT reset, so it still has (balanceBeforeWithdraw - withdrawAmount) + 1 ether.
        // The minimal invariant: the balance is at least 1 ether.
        // Actually we need a property that holds for all inputs in P but fails for M.
        // In P: after withdrawBalance the balance is 0; then addToBalance(1 ether) => balance = 1 ether exactly.
        // In M: after withdrawBalance the balance is unchanged; then addToBalance(1 ether) => balance = (old balance) + 1 ether, which is > 1 ether.
        // So the invariant: the balance equals exactly 1 ether.
        assertTrue(c.getBalance(user) == 1 ether);
    }
}
